// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address token) public {
        // Ensure token is not the zero address (optional, but avoids edge cases)
        vm.assume(token != address(0));

        // First call to addReward should succeed
        c.addReward(token);

        // Second call to addReward with the same token should revert in reference version
        try c.addReward(token) {
            // If it doesn't revert, the mutant is present
            assertTrue(false, "addReward should revert when adding an existing reward token");
        } catch {
            // Expected revert
            assertTrue(true);
        }
    }
}

